; ==================================================================
; SPRITE INITIALIZATION FUNCTIONS
; ==================================================================

init_sprites:
    call clear_all_sprites
    call load_sprite_patterns
    xor a
    ld (active_sprite_count), a
    ret

load_sprite_patterns:
    ; Load patterns for all active entities
    ; Entity 0: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 0
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (0 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 1: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 1
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (1 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 2: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 2
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (2 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 3: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 3
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (3 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 4: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 4
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (4 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 5: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 5
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (5 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 6: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 6
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (6 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 7: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 7
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (7 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 8: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 8
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (8 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 9: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 9
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (9 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 10: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 10
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (10 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 11: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 11
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (11 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 12: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 12
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (12 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ret

; ==================================================================
; SPRITE MANAGEMENT FUNCTIONS
; ==================================================================

; A = hardware sprite index, B = X, C = Y, D = pattern, E = color
show_sprite:
    ; Safety check: Ensure sprite index < 32
    cp 32
    ret nc

    ; Safety check: If Y=209 (invisible), force it to visible (e.g. 100)
    push af
    ld a, c
    cp 209
    jr nz, .y_ok
    ld c, 100       ; Force visible Y
.y_ok:
    pop af

    ; Calculate base address for sprite: index * 4
    ld l, a
    ld h, 0
    add hl, hl      ; index * 2
    add hl, hl      ; index * 4
    ; Add base of the attribute table
    ld de, sprite_attributes
    add hl, de      ; HL = &sprite_attributes[index * 4]

    ; Write attributes
    ld (hl), c      ; Y
    inc hl
    ld (hl), b      ; X
    inc hl
    ld (hl), d      ; Pattern
    inc hl
    ld (hl), e      ; Color

    ret

; Clear all sprites (set Y = SPRITE_INVISIBLE)
; OPTIMIZED: Uses faster increment method instead of ADD HL,DE
clear_all_sprites:
    ld hl, sprite_attributes
    ld b, 32
    ld a, SPRITE_INVISIBLE
.clear_loop:
    ld (hl), a      ; Set Y = SPRITE_INVISIBLE
    inc hl          ; Skip to X
    inc hl          ; Skip to Pattern
    inc hl          ; Skip to Color
    inc hl          ; Next sprite (4× INC HL = 24 cycles vs ADD HL,DE = 35 cycles)
    djnz .clear_loop
    ret

; Hide specific sprite (A = hardware sprite index)
hide_sprite:
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    ld de, sprite_attributes
    add hl, de
    ld (hl), SPRITE_INVISIBLE
    ret

; Copy sprite attributes from RAM to VRAM
update_sprites_to_vram:
    ld hl, sprite_attributes
    ld de, SPRATR
    ld bc, 128  ; 4 bytes per sprite
    call FAST_LDIRVM
    ret

; ==================================================================
; SPRITE CONSTANTS
; ==================================================================
SPRITE_INVISIBLE    EQU 224

